# Text Extraction Function

Here's a JavaScript function to extract text from a document, with a few variations depending on your needs:

## Basic Version - Extract all visible text from HTML document

```javascript
function extractTextFromDocument(doc = document) {
  // Use the document's body, fallback to documentElement
  const root = doc.body || doc.documentElement;

  if (!root) return '';

  return extractTextFromNode(root);
}

function extractTextFromNode(node) {
  let text = '';

  // Skip script, style, and other non-visible elements
  const skipTags = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'IFRAME', 'HEAD']);

  if (node.nodeType === Node.TEXT_NODE) {
    text += node.textContent;
  } else if (node.nodeType === Node.ELEMENT_NODE) {
    if (skipTags.has(node.tagName)) {
      return '';
    }

    // Check if element is hidden via inline style
    const style = window.getComputedStyle ? window.getComputedStyle(node) : null;
    if (style && (style.display === 'none' || style.visibility === 'hidden')) {
      return '';
    }

    for (const child of node.childNodes) {
      text += extractTextFromNode(child);
    }
  }

  return text;
}
```

## Cleaner Version - Normalize whitespace

```javascript
function extractCleanText(doc = document) {
  const root = doc.body || doc.documentElement;
  if (!root) return '';

  const rawText = extractTextFromNode(root);

  // Normalize whitespace: collapse multiple spaces/newlines
  return rawText
    .replace(/\s+/g, ' ')
    .trim();
}
```

## Advanced Version - Using TreeWalker (more efficient)

```javascript
function extractTextUsingTreeWalker(doc = document) {
  const root = doc.body || doc.documentElement;
  if (!root) return '';

  const skipTags = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'IFRAME', 'HEAD']);

  const walker = doc.createTreeWalker(
    root,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode(node) {
        const parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;

        if (skipTags.has(parent.tagName)) {
          return NodeFilter.FILTER_REJECT;
        }

        const style = window.getComputedStyle(parent);
        if (style.display === 'none' || style.visibility === 'hidden') {
          return NodeFilter.FILTER_REJECT;
        }

        return NodeFilter.FILTER_ACCEPT;
      }
    }
  );

  const textParts = [];
  let currentNode;

  while (currentNode = walker.nextNode()) {
    const trimmed = currentNode.textContent.trim();
    if (trimmed) {
      textParts.push(trimmed);
    }
  }

  return textParts.join(' ');
}
```

## Extract Text with Structure (preserves paragraphs)

```javascript
function extractStructuredText(doc = document) {
  const blockTags = new Set([
    'P', 'DIV', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6',
    'LI', 'TR', 'BLOCKQUOTE', 'PRE', 'BR'
  ]);
  const skipTags = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'IFRAME', 'HEAD']);

  function walk(node, lines, currentLine) {
    if (node.nodeType === Node.TEXT_NODE) {
      const text = node.textContent.replace(/\s+/g, ' ');
      if (text.trim()) {
        currentLine.push(text);
      }
    } else if (node.nodeType === Node.ELEMENT_NODE) {
      if (skipTags.has(node.tagName)) return currentLine;

      const isBlock = blockTags.has(node.tagName);

      if (isBlock && currentLine.length > 0) {
        lines.push(currentLine.join('').trim());
        currentLine = [];
      }

      for (const child of node.childNodes) {
        currentLine = walk(child, lines, currentLine);
      }

      if (isBlock && currentLine.length > 0) {
        lines.push(currentLine.join('').trim());
        currentLine = [];
      }
    }
    return currentLine;
  }

  const root = doc.body || doc.documentElement;
  if (!root) return '';

  const lines = [];
  let remaining = walk(root, lines, []);
  if (remaining.length > 0) {
    lines.push(remaining.join('').trim());
  }

  return lines.filter(line => line.length > 0).join('\n');
}
```

## Usage Examples

```javascript
// Extract from current page
const text1 = extractCleanText();
console.log(text1);

// Extract from a specific element instead of whole document
function extractFromElement(element) {
  return extractTextFromNode(element).replace(/\s+/g, ' ').trim();
}

const myDiv = document.getElementById('content');
const text2 = extractFromElement(myDiv);

// Extract structured text (with line breaks preserved)
const text3 = extractStructuredText();
console.log(text3);

// Use with an iframe's document
const iframeDoc = document.getElementById('myIframe').contentDocument;
const text4 = extractCleanText(iframeDoc);
```

## For Node.js (Server-Side) - Using a parsed HTML string

If you're working server-side with an HTML string (using something like `jsdom` or `cheerio`):

```javascript
// Using jsdom
const { JSDOM } = require('jsdom');

function extractTextFromHTML(htmlString) {
  const dom = new JSDOM(htmlString);
  return extractCleanText(dom.window.document);
}

// Using cheerio (simpler, no full DOM)
const cheerio = require('cheerio');

function extractTextWithCheerio(htmlString) {
  const $ = cheerio.load(htmlString);
  $('script, style, noscript').remove();
  return $('body').text().replace(/\s+/g, ' ').trim();
}
```

---

**Which version fits your use case?** Let me know if you need to:
- Extract text from a **PDF** instead of HTML
- Extract text from a **specific file type** (Word, etc.)
- Work with **Node.js** for server-side parsing
- Extract **metadata** along with text (title, author, etc.)

