	chunk.chunk_size = CHUNK_SIZE
	chunk.chunk_height = CHUNK_HEIGHT
	chunk.noise = noise
	chunk.position = Vector3(coord.x * CHUNK_SIZE, 0, coord.y * CHUNK_SIZE)
	add_child(chunk)
	chunk.generate()
	chunks[coord] = chunk

func get_block_global(x: int, y: int, z: int) -> int:
	var chunk_x := floori(float(x) / CHUNK_SIZE)
	var chunk_z := floori(float(z) / CHUNK_SIZE)
	var coord := Vector2i(chunk_x, chunk_z)
	if not chunks.has(coord):
		return 0
	var local_x := x - chunk_x * CHUNK_SIZE
	var local_z := z - chunk_z * CHUNK_SIZE
	return chunks[coord].get_block(local_x, y, local_z)
```

## Chunk.gd

```gdscript
extends Node3D
class_name Chunk

enum Block { AIR = 0, GRASS = 1, DIRT = 2, STONE = 3 }

var world: World
var chunk_coord: Vector2i
var chunk_size := 16
var chunk_height := 64
var noise: FastNoiseLite

var blocks := PackedByteArray()  # tamaño chunk_size * chunk_height * chunk_size

var mesh_instance: MeshInstance3D
var static_body: StaticBody3D

func _idx(x: int, y: int, z: int) -> int:
	return x + z * chunk_size + y * chunk_size * chunk_size

func generate():
	blocks.resize(chunk_size * chunk_height * chunk_size)

	for x in range(chunk_size):
		for z in range(chunk_size):
			var world_x := chunk_coord.x * chunk_size + x
			var world_z := chunk_coord.y * chunk_size + z
			var height_f := noise.get_noise_2d(world_x, world_z)
			var height := int((height_f * 0.5 + 0.5) * (chunk_height * 0.5)) + 16

			for y in range(chunk_height):
				var block := Block.AIR
				if y < height - 4:
					block = Block.STONE
				elif y < height - 1:
					block = Block.DIRT
				elif y == height - 1:
					block = Block.GRASS
				blocks[_idx(x, y, z)] = block

	build_mesh()

func get_block(x: int, y: int, z: int) -> int:
	if x < 0 or x >= chunk_size or z < 0 or z >= chunk_size or y < 0 or y >= chunk_height:
		# Consultar chunk vecino a través del mundo
		if world:
			return world.get_block_global(
				chunk_coord.x * chunk_size + x,
				y,
				chunk_coord.y * chunk_size + z
			)
		return Block.AIR
	return blocks[_idx(x, y, z)]

func is_solid(x: int, y: int, z: int) -> bool:
	return get_block(x, y, z) != Block.AIR

# Direcciones de las 6 caras: normal + 4 vértices (en orden CCW visto desde fuera)
const FACES := {
	"top":    { "normal": Vector3(0,1,0),  "verts": [Vector3(0,1,0), Vector3(0,1,1), Vector3(1,1,1), Vector3(1,1,0)] },
	"bottom": { "normal": Vector3(0,-1,0), "verts": [Vector3(0,0,1), Vector3(0,0,0), Vector3(1,0,0), Vector3(1,0,1)] },
	"north":  { "normal": Vector3(0,0,-1), "verts": [Vector3(1,0,0), Vector3(0,0,0), Vector3(0,1,0), Vector3(1,1,0)] },
	"south":  { "normal": Vector3(0,0,1),  "verts": [Vector3(0,0,1), Vector3(1,0,1), Vector3(1,1,1), Vector3(0,1,1)] },
	"east":   { "normal": Vector3(1,0,0),  "verts": [Vector3(1,0,1), Vector3(1,0,0), Vector3(1,1,0), Vector3(1,1,1)] },
	"west":   { "normal": Vector3(-1,0,0), "verts": [Vector3(0,0,0), Vector3(0,0,1), Vector3(0,1,1), Vector3(0,1,0)] },
}

const NEIGHBOR_OFFSET := {
	"top": Vector3i(0,1,0), "bottom": Vector3i(0,-1,0),
	"north": Vector3i(0,0,-1), "south": Vector3i(0,0,1),
	"east": Vector3i(1,0,0), "west": Vector3i(-1,0,0),
}

func get_block_color(block: int) -> Color:
	match block:
		Block.GRASS: return Color(0.2, 0.7, 0.2)
		Block.DIRT: return Color(0.45, 0.3, 0.15)
		Block.STONE: return Color(0.5, 0.5, 0.5)
		_: return Color.WHITE

func build_mesh():
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)

	for x in range(chunk_size):
		for y in range(chunk_height):
			for z in range(chunk_size):
				var block := blocks[_idx(x, y, z)]
				if block == Block.AIR:
					continue

				var color := get_block_color(block)

				for face_name in FACES.keys():
					var off: Vector3i = NEIGHBOR_OFFSET[face_name]
					if is_solid(x + off.x, y + off.y, z + off.z):
						continue  # cara oculta, no dibujar

					var face = FACES[face_name]
					var normal: Vector3 = face["normal"]
					var verts: Array = face["verts"]
					var base := Vector3(x, y, z)

					var v0 := base + verts[0]
					var v1 := base + verts[1]
					var v2 := base + verts[2]
					var v3 := base + verts[3]

					st.set_normal(normal)
					st.set_color(color)
					_add_vertex(st, v0)
					_add_vertex(st, v1)
					_add_vertex(st, v2)

					st.set_normal(normal)
					st.set_color(color)
					_add_vertex(st, v0)
					_add_vertex(st, v2)
					_add_vertex(st, v3)

	st.generate_normals()
	var mesh := st.commit()

	if mesh_instance:
		mesh_instance.queue_free()
	mesh_instance = MeshInstance3D.new()
	mesh_instance.mesh = mesh

	var mat := StandardMaterial3D.new()
	mat.vertex_color_use_as_albedo = true
	mesh_instance.material_override = mat

	add_child(mesh_instance)

	# Colisión
	if static_body:
		static_body.queue_free()
	static_body = StaticBody3D.new()
	var col := CollisionShape3D.new()
	var shape := ConcavePolygonShape3D.new()
	shape.set_faces(mesh.get_faces())
	col.shape = shape
	static_body.add_child(col)
	add_child(static_body)

func _add_vertex(st: SurfaceTool, v: Vector3):
	st.add_vertex(v)
```

## Notas de uso

1. Crea una escena con un `Node3D` raíz que tenga el script `World.gd`, y asigna al `player` un `CharacterBody3D` con cámara y controlador de movimiento.
2. Este ejemplo usa colores vertex en lugar de texturas (más simple); para texturas reales usarías un atlas y `set_uv()` en vez de `set_color()`.
3. Es una malla "naive" (cara por cara) con culling de caras ocultas — ya es mucho más eficiente que dibujar todos los cubos completos, pero para rendimiento avanzado se recomienda:
   - **Greedy meshing** (fusionar caras coplanares en rectángulos grandes).
   - Generar mallas en **hilos** (Godot `Thread` o `WorkerThreadPool`) para no bloquear el frame.
   - Usar `MultiMesh` o compute shaders para escenas masivas.
4. Para romper/colocar bloques: modifica `blocks[]` en el chunk correspondiente y llama a `build_mesh()` de nuevo (y de los chunks vecinos si el bloque está en el borde).

¿Quieres que añada minado/colocación de bloques con raycast desde el jugador, o el sistema de guardado/carga de chunks?

baseline.answer:
# Voxel Terrain Engine in Godot (GDScript)

Here's a complete voxel terrain engine similar to Minecraft, using chunks, noise-based generation, and mesh optimization.

## Project Structure
```
res://
  scripts/
    VoxelWorld.gd
    Chunk.gd
    VoxelData.gd
  main.tscn
```

## 1. VoxelData.gd - Block definitions

```gdscript
extends Node
class_name VoxelData

enum BlockType {
	AIR,
	GRASS,
	DIRT,
	STONE,
	SAND,
	WATER,
	WOOD,
	LEAVES,
	BEDROCK
}

const CHUNK_SIZE = 16
const CHUNK_HEIGHT = 128
const WORLD_HEIGHT_SCALE = 60
const WATER_LEVEL = 40

# UV coordinates in texture atlas (assuming 16x16 grid atlas)
const ATLAS_SIZE = 16.0

static func get_uv_offset(block_type: int, face: int) -> Vector2:
	# face: 0=top, 1=bottom, 2=side
	match block_type:
		BlockType.GRASS:
			if face == 0:
				return Vector2(0, 0) # grass top
			elif face == 1:
				return Vector2(2, 0) # dirt
			else:
				return Vector2(1, 0) # grass side
		BlockType.DIRT:
			return Vector2(2, 0)
		BlockType.STONE:
			return Vector2(3, 0)
		BlockType.SAND:
			return Vector2(4, 0)
		BlockType.WOOD:
			if face == 0 or face == 1:
				return Vector2(6, 0)
			return Vector2(5, 0)
		BlockType.LEAVES:
			return Vector2(7, 0)
		BlockType.BEDROCK:
			return Vector2(8, 0)
		_:
			return Vector2(3, 0)

static func is_transparent(block_type: int) -> bool:
	return block_type == BlockType.AIR or block_type == BlockType.WATER or block_type == BlockType.LEAVES

static func is_solid(block_type: int) -> bool:
	return block_type != BlockType.AIR and block_type != BlockType.WATER
```

## 2. Chunk.gd - Individual chunk mesh generation

```gdscript
extends StaticBody3D
class_name Chunk

var chunk_position: Vector3i
var world_ref: Node
var blocks: Dictionary = {} # Vector3i -> block_type
var mesh_instance: MeshInstance3D
var collision_shape: CollisionShape3D
var is_generated := false
var is_meshed := false

const CHUNK_SIZE = VoxelData.CHUNK_SIZE
const CHUNK_HEIGHT = VoxelData.CHUNK_HEIGHT

func _init(pos: Vector3i, world: Node):
	chunk_position = pos
	world_ref = world

func _ready():
	mesh_instance = MeshInstance3D.new()
	add_child(mesh_instance)

	collision_shape = CollisionShape3D.new()
	add_child(collision_shape)

	var mat = StandardMaterial3D.new()
	mat.albedo_texture = load("res://textures/atlas.png") if ResourceLoader.exists("res://textures/atlas.png") else null
	mat.vertex_color_use_as_albedo = false
	mat.roughness = 1.0
	mesh_instance.material_override = mat

func get_block(x: int, y: int, z: int) -> int:
	if y < 0 or y >= CHUNK_HEIGHT:
		return VoxelData.BlockType.AIR

	if x < 0 or x >= CHUNK_SIZE or z < 0 or z >= CHUNK_SIZE:
		# Get from neighboring chunk
		var world_x = chunk_position.x * CHUNK_SIZE + x
		var world_z = chunk_position.z * CHUNK_SIZE + z
		return world_ref.get_block_world(world_x, y, world_z)

	var key = Vector3i(x, y, z)
	return blocks.get(key, VoxelData.BlockType.AIR)

func set_block(x: int, y: int, z: int, block_type: int):
	if y < 0 or y >= CHUNK_HEIGHT or x < 0 or x >= CHUNK_SIZE or z < 0 or z >= CHUNK_SIZE:
		return
	var key = Vector3i(x, y, z)
	if block_type == VoxelData.BlockType.AIR:
		blocks.erase(key)
	else:
		blocks[key] = block_type

func generate_terrain(noise: FastNoiseLite, noise2: FastNoiseLite):
	for x in range(CHUNK_SIZE):
		for z in range(CHUNK_SIZE):
			var world_x = chunk_position.x * CHUNK_SIZE + x
			var world_z = chunk_position.z * CHUNK_SIZE + z

			var height_val = noise.get_noise_2d(world_x, world_z)
			var height = int((height_val + 1.0) * 0.5 * VoxelData.WORLD_HEIGHT_SCALE) + 30

			for y in range(CHUNK_HEIGHT):
				var block_type = VoxelData.BlockType.AIR

				if y == 0:
					block_type = VoxelData.BlockType.BEDROCK
				elif y < height - 4:
					block_type = VoxelData.BlockType.STONE
				elif y < height - 1:
					block_type = VoxelData.BlockType.DIRT
				elif y == height - 1:
					if height <= VoxelData.WATER_LEVEL + 2:
						block_type = VoxelData.BlockType.SAND
					else:
						block_type = VoxelData.BlockType.GRASS
				elif y < VoxelData.WATER_LEVEL and y >= height:
					block_type = VoxelData.BlockType.WATER

				if block_type != VoxelData.BlockType.AIR:
					set_block(x, y, z, block_type)

			# Simple tree generation
			if height > VoxelData.WATER_LEVEL + 2:
				var tree_noise = noise2.get_noise_2d(world_x, world_z)
				if tree_noise > 0.7:
					generate_tree(x, height, z)

	is_generated = true

func generate_tree(x: int, base_y: int, z: int):
	var tree_height = randi_range(4, 6)

	for i in range(tree_height):
		set_block(x, base_y + i, z, VoxelData.BlockType.WOOD)

	# Simple leaves
	for lx in range(-2, 3):
		for ly in range(-1, 3):
			for lz in range(-2, 3):
				if abs(lx) + abs(ly) + abs(lz) < 4:
					if not (lx == 0 and lz == 0 and ly < 2):
						var leaf_y = base_y + tree_height - 2 + ly
						set_block(x + lx, leaf_y, z + lz, VoxelData.BlockType.LEAVES)

func generate_mesh():
	var surface_tool = SurfaceTool.new()
	surface_tool.begin(Mesh.PRIMITIVE_TRIANGLES)

	var vertices = PackedVector3Array()
	var normals = PackedVector3Array()
	var uvs = PackedVector2Array()
	var indices = PackedInt32Array()

	for x in range(CHUNK_SIZE):
		for y in range(CHUNK_HEIGHT):
			for z in range(CHUNK_SIZE):
				var block = get_block(x, y, z)
				if block == VoxelData.BlockType.AIR:
					continue

				add_block_mesh(x, y, z, block, vertices, normals, uvs, indices)

	if vertices.size() == 0:
		is_meshed = true
		return

	var arrays = []
	arrays.resize(Mesh.ARRAY_MAX)
	arrays[Mesh.ARRAY_VERTEX] = vertices
	arrays[Mesh.ARRAY_NORMAL] = normals
	arrays[Mesh.ARRAY_TEX_UV] = uvs
	arrays[Mesh.ARRAY_INDEX] = indices

	var array_mesh = ArrayMesh.new()
	array_mesh.add_surface_from_arrays(Mesh.PRIMITIVE_TRIANGLES, arrays)

	mesh_instance.mesh = array_mesh

	# Generate collision
	var shape = array_mesh.create_trimesh_shape()
	collision_shape.shape = shape

	is_meshed = true

func add_block_mesh(x: int, y: int, z: int, block_type: int, 
	vertices: PackedVector3Array, normals: PackedVector3Array, 
	uvs: PackedVector2Array, indices: PackedInt32Array):

	var pos = Vector3(x, y, z)

	# Check each face - only render if neighbor is transparent
	# Top face
	if VoxelData.is_transparent(get_block(x, y + 1, z)):
		add_face(pos, Vector3.UP, block_type, 0, vertices, normals, uvs, indices)

	# Bottom face
	if VoxelData.is_transparent(get_block(x, y - 1, z)):
		add_face(pos, Vector3.DOWN, block_type, 1, vertices, normals, uvs, indices)

	# North face (+Z)
	if VoxelData.is_transparent(get_block(x, y, z + 1)):
		add_face(pos, Vector3.FORWARD, block_type, 2, vertices, normals, uvs, indices)

	# South face (-Z)
	if VoxelData.is_transparent(get_block(x, y, z - 1)):
		add_face(pos, Vector3.BACK, block_type, 2, vertices, normals, uvs, indices)

	# East face (+X)
	if VoxelData.is_transparent(get_block(x + 1, y, z)):
		add_face(pos, Vector3.RIGHT, block_type, 2, vertices, normals, uvs, indices)

	# West face (-X)
	if VoxelData.is_transparent(get_block(x - 1, y, z)):
		add_face(pos, Vector3.LEFT, block_type, 2, vertices, normals, uvs, indices)

func add_face(pos: Vector3, normal: Vector3, block_type: int, face_index: int,
	vertices: PackedVector3Array, normals: PackedVector3Array,
	uvs: PackedVector2Array, indices: PackedInt32Array):

	var start_idx = vertices.size()
	var face_verts: Array[Vector3] = []

	if normal == Vector3.UP:
		face_verts = [
			pos + Vector3(0, 1, 0), pos + Vector3(0, 1, 1),
			pos + Vector3(1, 1, 1), pos + Vector3(1, 1, 0)
		]
	elif normal == Vector3.DOWN:
		face_verts = [
			pos + Vector3(0, 0, 1), pos + Vector3(0, 0, 0),
			pos + Vector3(1, 0, 0), pos + Vector3(1, 0, 1)
		]
	elif normal == Vector3.FORWARD:
		face_verts = [
			pos + Vector3(1, 0, 1), pos + Vector3(1, 1, 1),
			pos + Vector3(0, 1, 1), pos + Vector3(0, 0, 1)
		]
	elif normal == Vector3.BACK:
		face_verts = [
			pos + Vector3(0, 0, 0), pos + Vector3(0, 1, 0),
			pos + Vector3(1, 1, 0), pos + Vector3(1, 0, 0)
		]
	elif normal == Vector3.RIGHT:
		face_verts = [
			pos + Vector3(1, 0, 0), pos + Vector3(1, 1, 0),
			pos + Vector3(1, 1, 1), pos + Vector3(1, 0, 1)
		]
	elif normal == Vector3.LEFT:
		face_verts = [
			pos + Vector3(0, 0, 1), pos + Vector3(0, 1, 1),
			pos + Vector3(0, 1, 0), pos + Vector3(0, 0, 0)
		]

	for v in face_verts:
		vertices.append(v)
		normals.append(normal)

	var atlas_offset = VoxelData.get_uv_offset(block_type, face_index)
	var uv_size = 1.0 / VoxelData.ATLAS_SIZE
	var u0 = atlas_offset.x * uv_size
	var v0 = atlas_offset.y * uv_size

	uvs.append(Vector2(u0, v0 + uv_size))
	uvs.append(Vector2(u0, v0))
	uvs.append(Vector2(u0 + uv_size, v0))
	uvs.append(Vector2(u0 + uv_size, v0 + uv_size))

	indices.append(start_idx)
	indices.append(start_idx + 1)
	indices.append(start_idx + 2)
	indices.append(start_idx)
	indices.append(start_idx + 2)
	indices.append(start_idx + 3)
```

## 3. VoxelWorld.gd - World manager

```gdscript
extends Node3D
class_name VoxelWorld

var chunks: Dictionary = {} # Vector3i -> Chunk
var noise: FastNoiseLite
var tree_noise: FastNoiseLite

@export var render_distance: int = 8
@export var player: Node3D

var chunks_to_generate: Array[Vector3i] = []
var chunks_to_mesh: Array[Vector3i] = []
var chunks_pending_update: Dictionary = {}

func _ready():
	setup_noise()
	call_deferred("update_chunks_around_player")

func setup_noise():
	noise = FastNoiseLite.new()
	noise.seed = randi()
	noise.frequency = 0.01
	noise.fractal_octaves = 4
	noise.fractal_lacunarity = 2.0
	noise.fractal_gain = 0.5

	tree_noise = FastNoiseLite.new()
	tree_noise.seed = randi() + 1000
	tree_noise.frequency = 0.5
	tree_noise.noise_type = FastNoiseLite.TYPE_VALUE

func _process(_delta):
	process_chunk_queue()

	if player:
		update_chunks_around_player()

func get_chunk_pos_from_world(world_pos: Vector3) -> Vector3i:
	return Vector3i(
		floori(world_pos.x / VoxelData.CHUNK_SIZE),
		0,
		floori(world_pos.z / VoxelData.CHUNK_SIZE)
	)

func update_chunks_around_player():
	if not player:
		return

	var player_chunk = get_chunk_pos_from_world(player.global_position)

	# Queue new chunks
	for x in range(-render_distance, render_distance + 1):
		for z in range(-render_distance, render_distance + 1):
			var dist = Vector2(x, z).length()
			if dist > render_distance:
				continue

			var chunk_pos = Vector3i(player_chunk.x + x, 0, player_chunk.z + z)

			if not chunks.has(chunk_pos) and not chunks_to_generate.has(chunk_pos):
				chunks_to_generate.append(chunk_pos)

	# Sort by distance to player
	chunks_to_generate.sort_custom(func(a, b):
		var da = Vector2(a.x - player_chunk.x, a.z - player_chunk.z).length()
		var db = Vector2(b.x - player_chunk.x, b.z - player_chunk.z).length()
		return da < db
	)

	# Unload far chunks
	var chunks_to_remove = []
	for chunk_pos in chunks.keys():
		var dist = Vector2(chunk_pos.x - player_chunk.x, chunk_pos.z - player_chunk.z).length()
		if dist > render_distance + 2:
			chunks_to_remove.append(chunk_pos)

	for chunk_pos in chunks_to_remove:
		unload_chunk(chunk_pos)

func process_chunk_queue():
	var chunks_per_frame = 2

	# Generate terrain data
	for i in range(min(chunks_per_frame, chunks_to_generate.size())):
		var chunk_pos = chunks_to_generate.pop_front()
		if not chunks.has(chunk_pos):
			create_chunk(chunk_pos)

	# Generate meshes (after neighbors exist for proper culling)
	for i in range(min(chunks_per_frame, chunks_to_mesh.size())):
		var chunk_pos = chunks_to_mesh.pop_front()
		if chunks.has(chunk_pos):
			var chunk = chunks[chunk_pos]
			if chunk.is_generated and not chunk.is_meshed:
				chunk.generate_mesh()

func create_chunk(chunk_pos: Vector3i):
	var chunk = Chunk.new(chunk_pos, self)
	chunk.name = "Chunk_%d_%d" % [chunk_pos.x, chunk_pos.z]
	add_child(chunk)
	chunk.position = Vector3(chunk_pos.x * VoxelData.CHUNK_SIZE, 0, chunk_pos.z * VoxelData.CHUNK_SIZE)

	chunks[chunk_pos] = chunk
	chunk.generate_terrain(noise, tree_noise)

	chunks_to_mesh.append(chunk_pos)

	# Queue neighbor remeshing if they exist (edge blocks changed visibility)
	queue_neighbor_remesh(chunk_pos)

func queue_neighbor_remesh(chunk_pos: Vector3i):
	var neighbors = [
		Vector3i(chunk_pos.x + 1, 0, chunk_pos.z),
		Vector3i(chunk_pos.x - 1, 0, chunk_pos.z),
		Vector3i(chunk_pos.x, 0, chunk_pos.z + 1),
		Vector3i(chunk_pos.x, 0, chunk_pos.z - 1)
	]

	for n_pos in neighbors:
		if chunks.has(n_pos) and chunks[n_pos].is_meshed:
			if not chunks_to_mesh.has(n_pos):
				chunks_to_mesh.append(n_pos)

func unload_chunk(chunk_pos: Vector3i):
	if chunks.has(chunk_pos):
		chunks[chunk_pos].queue_free()
		chunks.erase(chunk_pos)

func get_block_world(world_x: int, world_y: int, world_z: int) -> int:
	var chunk_pos = Vector3i(
		floori(float(world_x) / VoxelData.CHUNK_SIZE),
		0,
		floori(float(world_z) / VoxelData.CHUNK_SIZE)
	)

	if not chunks.has(chunk_pos):
		return VoxelData.BlockType.AIR

	var chunk = chunks[chunk_pos]
	var local_x = world_x - chunk_pos.x * VoxelData.CHUNK_SIZE
	var local_z = world_z - chunk_pos.z * VoxelData.CHUNK_SIZE

	return chunk.get_block(local_x, world_y, local_z)

func set_block_world(world_x: int, world_y: int, world_z: int, block_type: int):
	var chunk_pos = Vector3i(
		floori(float(world_x) / VoxelData.CHUNK_SIZE),
		0,
		floori(float(world_z) / VoxelData.CHUNK_SIZE)
	)

	if not chunks.has(chunk_pos):
		return

	var chunk = chunks[chunk_pos]
	var local_x = world_x - chunk_pos.x * VoxelData.CHUNK_SIZE
	var local_z = world_z - chunk_pos.z * VoxelData.CHUNK_SIZE

	chunk.set_block(local_x, world_y, local_z, block_type)
	chunk.generate_mesh()

	# Update neighboring chunks if block is on edge
	if local_x == 0:
		remesh_neighbor(Vector3i(chunk_pos.x - 1, 0, chunk_pos.z))
	elif local_x == VoxelData.CHUNK_SIZE - 1:
		remesh_neighbor(Vector3i(chunk_pos.x + 1, 0, chunk_pos.z))

	if local_z == 0:
		remesh_neighbor(Vector3i(chunk_pos.x, 0, chunk_pos.z - 1))
	elif local_z == VoxelData.CHUNK_SIZE - 1:
		remesh_neighbor(Vector3i(chunk_pos.x, 0, chunk_pos.z + 1))

func remesh_neighbor(chunk_pos: Vector3i):
	if chunks.has(chunk_pos):
		chunks[chunk_pos].generate_mesh()

func raycast_voxel(from: Vector3, to: Vector3) -> Dictionary:
	var space_state = get_world_3d().direct_space_state
	var query = PhysicsRayQueryParameters3D.create(from, to)
	var result = space_state.intersect_ray(query)

	if result:
		var pos = result.position - result.normal * 0.5
		var block_pos = Vector3i(floori(pos.x), floori(pos.y), floori(pos.z))
		var place_pos = Vector3i(
			floori(pos.x + result.normal.x),
			floori(pos.y + result.normal.y),
			floori(pos.z + result.normal.z)
		)
		return {
			"hit": true,
			"block_position": block_pos,
			"place_position": place_pos,
			"normal": result.normal
		}

	return {"hit": false}
```

## 4. PlayerController.gd - Basic FPS controller for testing

```gdscript
extends CharacterBody3D
class_name PlayerController

@export var speed: float = 8.0
@export var jump_velocity: float = 8.0
@export var mouse_sensitivity: float = 0.003
@export var gravity: float = 20.0

@onready var camera: Camera3D = $Camera3D
@onready var raycast: RayCast3D = $Camera3D/RayCast3D

var world: VoxelWorld

func _ready():
	Input.mouse_mode = Input.MOUSE_MODE_CAPTURED
	world = get_node("/root/Main/VoxelWorld") # Adjust path as needed

func _input(event):
	if event is InputEventMouseMotion and Input.mouse_mode == Input.MOUSE_MODE_CAPTURED:
		rotate_y(-event.relative.x * mouse_sensitivity)
		camera.rotate_x(-event.relative.y * mouse_sensitivity)
		camera.rotation.x = clamp(camera.rotation.x, -PI/2, PI/2)

	if event.is_action_pressed("ui_cancel"):
		Input.mouse_mode = Input.MOUSE_MODE_VISIBLE if Input.mouse_mode == Input.MOUSE_MODE_CAPTURED else Input.MOUSE_MODE_CAPTURED

	if event is InputEventMouseButton and event.pressed:
		if event.button_index == MOUSE_BUTTON_LEFT:
			break_block()
		elif event.button_index == MOUSE_BUTTON_RIGHT:
			place_block()

func _physics_process(delta):
	if not is_on_floor():
		velocity.y -= gravity * delta

	if Input.is_action_just_pressed("ui_accept") and is_on_floor():
		velocity.y = jump_velocity

	var input_dir = Input.get_vector("ui_left", "ui_right", "ui_up", "ui_down")
	var direction = (transform.basis * Vector3(input_dir.x, 0, input_dir.y)).normalized()

	if direction:
		velocity.x = direction.x * speed
		velocity.z = direction.z * speed
	else:
		velocity.x = move_toward(velocity.x, 0, speed)
		velocity.z = move_toward(velocity.z, 0, speed)

	move_and_slide()

func break_block():
	if not world:
		return

	var from = camera.global_position
	var to = from + camera.global_transform.basis.z * -5

	var result = world.raycast_voxel(from, to)
	if result.hit:
		var pos = result.block_position
		world.set_block_world(pos.x, pos.y, pos.z, VoxelData.BlockType.AIR)

func place_block():
	if not world:
		return

	var from = camera.global_position
	var to = from + camera.global_transform.basis.z * -5

	var result = world.raycast_voxel(from, to)
	if result.hit:
		var pos = result.place_position
		world.set_block_world(pos.x, pos.y, pos.z, VoxelData.BlockType.STONE)
```

## Setup Instructions

1. **Create the scene structure:**
   - Main (Node3D)
     - VoxelWorld (Node3D) - attach VoxelWorld.gd
     - Player (CharacterBody3D) - attach PlayerController.gd
       - Camera3D
         - RayCast3D
     - DirectionalLight3D
     - WorldEnvironment

2. **Create a texture atlas** at `res://textures/atlas.png` (16x16 grid of block textures)

3. **Configure input map** in Project Settings for movement (ui_left, ui_right, ui_up, ui_down, ui_accept)

4. **Assign the player** to the VoxelWorld's `player` export variable

## Key Features

- **Chunked terrain** (16x16x128 chunks)
- **Greedy face culling** - only renders visible faces
- **Noise-based terrain generation** with height maps
- **Simple tree generation**
- **Block breaking/placing** via raycasting
- **Dynamic chunk loading/unloading** based on player position
- **Texture atlas UV mapping**
- **Collision generation** for physics

## Performance Improvements to Consider

- **Greedy meshing** - merge adjacent same-type faces into larger quads
- **Multi-threading** - generate chunks on separate threads
- **LOD system** - reduce detail for distant chunks
- **Frustum culling** - already handled by Godot's visibility system
- **Chunk data serialization** for saving/loading worlds

This gives you a solid foundation for a voxel engine. Let me know if you'd like me to expand on any particular system (greedy meshing, multithreading, biomes, etc.)!
